         ...filters,
         text: debouncedSearch || undefined,
-        pageSize: 20,
-        page: 1,
+        pageSize: PAGE_SIZE,
+        page: currentPage,
       });
       const mapped = (response.tasks ?? []).map(mapApiTask);
       setTasks(mapped);
+      setTotalCount(response.total ?? 0);
